# Actuarial review: age bands have gaps (e.g. 29.5 and 69.5 use the default),
# empty ages receive the under-25 factor, and there is no age/power/exposure
# validation. The minimum is applied annually before exposure; negative
# exposure is permitted. Area errors take precedence over bonus-malus errors.

from decimal import Decimal, ROUND_HALF_UP
import math
import pandas as pd

BASE_RATE = 180.0
MIN_ANNUAL = 90.25


def mtpl_premium(driv_age, veh_power, bonus_malus, area, exposure) -> float:
    if driv_age is None or pd.isna(driv_age):
        age = 0.0
    else:
        age = driv_age
    if age < 25:
        f_age = 1.75
    elif 25 <= age <= 29:
        f_age = 1.25
    elif 30 <= age <= 69:
        f_age = 1.0
    else:
        f_age = 1.125

    if veh_power <= 5:
        f_pow = 0.875
    elif veh_power <= 9:
        f_pow = 1.0
    else:
        f_pow = 1.25

    cleaned = area.strip(' ').upper()
    if cleaned in ('A', 'B'):
        f_area = 0.875
    elif cleaned in ('C', 'D'):
        f_area = 1.0
    elif cleaned in ('E', 'F'):
        f_area = 1.25
    else:
        raise ValueError('Unknown area: ' + area)
    if bonus_malus < 50 or bonus_malus > 350:
        raise ValueError('BonusMalus out of range')

    annual = BASE_RATE * f_age * f_pow * f_area * bonus_malus / 100
    if annual < MIN_ANNUAL:
        annual = MIN_ANNUAL
    amount = annual * exposure
    # Excel stores numeric values to 15 significant decimal digits before ROUND.
    held = Decimal(format(amount, '.15g'))
    return float(held.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))


def premium_table(df: pd.DataFrame) -> pd.Series:
    results = []
    for age, power, bm, area, exposure in df[['DrivAge', 'VehPower', 'BonusMalus', 'Area', 'Exposure']].itertuples(index=False, name=None):
        try:
            results.append(mtpl_premium(age, power, bm, area, exposure))
        except ValueError:
            results.append(float('nan'))
    return pd.Series(results, index=df.index, dtype=float)

